using Microsoft.Win32;using System.Diagnostics;namespace Luma;public static class BrowserRegistry{public static void RegisterPerUser(string exe){var cmd=$"\"{exe}\" \"%1\"";using var classes=Registry.CurrentUser.CreateSubKey(@"Software\Classes");using(var p=classes.CreateSubKey("LumaURL")){p.SetValue("","Luma URL");p.SetValue("URL Protocol","");p.CreateSubKey(@"shell\open\command")!.SetValue("",cmd);}using var c=Registry.CurrentUser.CreateSubKey(@"Software\Clients\StartMenuInternet\Luma");c.SetValue("","Luma Browser");var caps=c.CreateSubKey("Capabilities")!;caps.SetValue("ApplicationName","Luma Browser");caps.SetValue("ApplicationDescription","Luma Browser");var urls=caps.CreateSubKey("URLAssociations")!;urls.SetValue("http","LumaURL");urls.SetValue("https","LumaURL");Registry.CurrentUser.CreateSubKey(@"Software\RegisteredApplications")!.SetValue("Luma",@"Software\Clients\StartMenuInternet\Luma\Capabilities");}public static void OpenDefaultAppsSettings()=>Process.Start(new ProcessStartInfo("ms-settings:defaultapps?registeredAppUser=Luma"){UseShellExecute=true});}